      SUBROUTINE FOCUS3CC     CALCULATES THIRD-ORDER TRANSFER MATRIX ELEMENTS FOR A QUADRUPOLEC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESCC-----------------------------------------------------------------------------C      J = JQUAD      JO = 4 - J      CS = R(J,J)      SN = R(J,J+1)      CSO = R(JO,JO)      SNO = R(JO,JO+1)      IF (J .EQ. 1) KLM = 1      IF (J .EQ. 3) KLM = 10      U(J,KLM) = KQ2**2*(13.*CS*SN**2 - 9.*L*SN)/48.      U(J+1,KLM) = - KQ2**2*(7.*SN + 15.*KQ2*SN**3     1           + 9.*L*CS)/48.      IF (J .EQ. 1) KLM = 2      IF (J .EQ. 3) KLM = 16      U(J,KLM) = KQ2*(- 22.*SN + 26.*KQ2*SN**3 + 6.*L*CS)/32.      U(J+1,KLM) = 3.*KQ2**2*(5.*CS*SN**2 - L*SN)/16.      IF (J .EQ. 1) KLM = 3      IF (J .EQ. 3) KLM = 19      U(J,KLM) = - KQ2*(13.*CS*SN**2 + 3.*L*SN)/16.      U(J+1,KLM) = KQ2*(- 26.*SN + 30.*KQ2*SN**3     1           - 6.*L*CS)/32.      IF (J .EQ. 1) KLM = 4      IF (J .EQ. 3) KLM = 20      U(J,KLM) = (- 9.*SN - 13.*KQ2*SN**3 + 9.*L*CS)/48.      U(J+1,KLM) = - KQ2*(5.*CS*SN**2 + 3.*L*SN)/16.      IF (J .EQ. 1) KLM = 8      IF (J .EQ. 3) KLM = 5      U(J,KLM) = KQ2**2*(- 3.*CS*SNO**2 + 2.*L*SN     1         - 3.*SN*SNO*CSO)/16.      U(J+1,KLM) = KQ2**2*(2.*L*CS - 9.*CS*CSO*SNO - 9.*SN     1           - 11.*KQ2*SN*SNO**2)/16.      IF (J .EQ. 1) KLM = 14      IF (J .EQ. 3) KLM = 6      U(J,KLM) = 3.*KQ2*(- CS*CSO*SNO + SN - KQ2*SN*SNO**2)/8.      U(J+1,KLM) = KQ2**2*(- 9.*CS*SNO**2 - 11.*SN*SNO*CSO)/8.      IF (J .EQ. 1) KLM = 17      IF (J .EQ. 3) KLM = 7      U(J,KLM) = - KQ2*(3.*CS*SNO**2 + 2.*L*SN     1         + 3.*SN*CSO*SNO)/16.      U(J+1,KLM) = - KQ2*(2.*L*CS + 9.*CS*CSO*SNO     1         + 11.*KQ2*SN*SNO**2 + 5.*SN)/16.      IF (J .EQ. 1) KLM = 9      IF (J .EQ. 3) KLM = 11      U(J,KLM) = KQ2*(3.*CS*CSO*SNO - 2.*L*CS - 3.*SN*CSO**2     1         - 6.*SN)/16.      U(J+1,KLM) = KQ2**2*(11.*CS*SNO**2 + 2.*L*SN     1           - 9.*SN*CSO*SNO)/16.      IF (J .EQ. 1) KLM = 15      IF (J .EQ. 3) KLM = 12      U(J,KLM) = 3.*KQ2*(CS*SNO**2 - SN*CSO*SNO)/8.      U(J+1,KLM) = KQ2*(11.*CS*CSO*SNO - 3.*SN     1           - 9.*KQ2*SN*SNO**2)/8.      IF (J .EQ. 1) KLM = 18      IF (J .EQ. 3) KLM = 13      U(J,KLM) = (3.*CS*CSO*SNO + 2.*L*CS - 3.*SN*CSO**2     1         - 2.*SN)/16.      U(J+1,KLM) = KQ2*(11.*CS*SNO**2 - 2.*L*SN     1           - 9.*SN*CSO*SNO)/16.      U(J,50+J) = - KQ2*(3.*L*SN + L**2*CS)/8.      U(J,51+J) = (- KQ2*L**2*SN + L*CS - SN)/8.      U(J+1,50+J) = KQ2*(- 5.*L*CS - 3.*SN + KQ2*L**2*SN)/8.      U(J+1,51+J) = KQ2*(- 3.*L*SN - L**2*CS)/8.      RETURN      END